export interface GoalEventSchema {
  /**
   * The goal key
   */
  'goal': string;
  /**
   * Your own unique ID for this event (application number, order ID, transaction reference), 1-128 characters. Idempotency key with `goal`.
   */
  'reference': string;
  /**
   * The Clikgate click id
   */
  'click_id'?: string | null;
  /**
   * An offline or creator code
   */
  'code'?: string | null;
  'value'?: Value | null;
  /**
   * ISO 4217; defaults to the goal's default_currency; ignored without a value
   */
  'currency'?: string | null;
  /**
   * Your statement that this is the customer's first such event
   */
  'is_first'?: boolean | null;
  /**
   * Defaults to now; ≤ 5 minutes ahead
   */
  'occurred_at'?: string | null;
  /**
   * Payment provider (Payment goals); default custom when sent by a server
   */
  'provider'?: Provider | null;
  /**
   * ≤ 8 KB; refused in private mode
   */
  'metadata'?: { [key: string]: any; } | null;
  /**
   * The end user's consent; refused in private mode
   */
  'consent'?: ServerConsentSchema | null;
  /**
   * Optional label for the person behind this goal's click, 1-80 characters; "" clears it
   */
  'label'?: string | null;
  /**
   * The customer's email / phone (server key; refused in private mode)
   */
  'customer'?: ConversionCustomerSchema | null;
  /**
   * SHA-256 (lowercase hex) of the trimmed, lowercased email (server key only)
   */
  'hashed_email'?: string | null;
  /**
   * SHA-256 (lowercase hex) of the phone in E.164 with the + (server key only)
   */
  'hashed_phone_e164'?: string | null;
  /**
   * SHA-256 (lowercase hex) of the phone digits with the country code, no + (server key only)
   */
  'hashed_phone_digits'?: string | null;
  /**
   * How the click ID was kept (server SDK `click_ids.context`)
   */
  'kept_by'?: 'server_cookie' | 'script_cookie' | 'form' | 'payment_metadata' | 'unknown' | null;
  /**
   * The visitor's browser engine, parsed by the SDK (every iPhone browser is webkit_ios)
   */
  'browser_engine'?: 'webkit_ios' | 'safari_mac' | 'chromium' | 'gecko' | 'other' | null;
  /**
   * The visitor's platform, parsed by the SDK
   */
  'platform'?: 'ios' | 'android' | 'macos' | 'windows' | 'linux' | 'other' | null;
}

