/**
 * Normal units, never minor units (₦2,000,000 is 2000000; decimals allowed up to the currency's ISO 4217 exponent): a JSON number or a numeric string, ≥ 0, at most 15 significant digits.
 */
export type Value = number | string;

/**
 * Value ÷ cost (sales value, not margin): healthy ≥ 3, ok 1-3, below_cost < 1.
 */
export type ValueBand = 'healthy' | 'ok' | 'below_cost';

/**
 * Whether goal events carry a value.
 */
export type ValueMode = 'none' | 'optional' | 'required';

/**
 * Why value columns are empty: the cohort (or its 90-day fallback) has fewer than 30 customers.
 */
export type ValueReason = 'not_enough_history' | 'not_enough_customers';

